#!/usr/bin/env bun
/**
 * @description Database seed script for creating admin users
 * Loads admin user configuration from @apps/server/src/config.ts and creates
 * users with ADMIN role and phone OTP authentication.
 *
 * Usage:
 *   bun run db:seed          # From packages/db
 *   bun run db:seed          # From project root (via workspace script)
 */

import "dotenv/config";
import { getPrismaClient } from "../src/client.js";

// Import SEED_ADMIN_USERS from server seed config using relative path
// This avoids loading the full config validation which requires all env vars
// Using .ts extension since Bun handles TypeScript natively
const { SEED_ADMIN_USERS } = await import(
  "../../../apps/server/src/seed-config.ts"
);

const prisma = getPrismaClient();

/**
 * Seed admin users into the database
 */
async function seedAdminUsers() {
  console.log("🌱 Starting admin user seed...\n");

  if (SEED_ADMIN_USERS.length === 0) {
    console.log("⚠️  No admin users configured in SEED_ADMIN_USERS");
    console.log(
      "   Add users to apps/server/src/config.ts to seed admin accounts\n",
    );
    return;
  }

  let created = 0;
  let skipped = 0;

  for (const adminUser of SEED_ADMIN_USERS) {
    try {
      // Check if user already exists by email
      const existingUser = await prisma.user.findUnique({
        where: { email: adminUser.email },
      });

      if (existingUser) {
        console.log(`⏭️  Skipped: ${adminUser.email} (already exists)`);
        skipped++;
        continue;
      }

      // Create admin user with verified phone/email
      const user = await prisma.user.create({
        data: {
          email: adminUser.email,
          emailVerified: true,
          phoneNumber: adminUser.phoneNumber,
          phoneNumberVerified: true,
          name: adminUser.name,
          firstName: adminUser.firstName,
          lastName: adminUser.lastName,
          role: "ADMIN",
          createdAt: new Date(),
          updatedAt: new Date(),
        },
      });

      console.log(`✅ Created: ${user.email} (${user.name}) - ID: ${user.id}`);
      created++;
    } catch (error) {
      console.error(`❌ Failed to create ${adminUser.email}:`, error);
      throw error;
    }
  }

  console.log(`\n🎉 Seed complete: ${created} created, ${skipped} skipped\n`);
}

/**
 * Main entry point
 */
async function main() {
  try {
    await seedAdminUsers();
  } catch (error) {
    console.error("\n❌ Seed failed:", error);
    process.exit(1);
  } finally {
    await prisma.$disconnect();
  }
}

// Run if executed directly
if (import.meta.main) {
  main();
}
